if (!function_exists('icon')) {
    /**
     * Inline Lucide SVG icon. CSP-safe (no external asset, no inline handler).
     * @param string $name  semantic icon name (see $__LUCIDE keys)
     * @param int    $size  px (width & height)
     * @param string $class extra CSS classes
     * @param string $attr  extra raw attributes (e.g. 'aria-hidden="true"')
     */
    function icon(string $name, int $size = 18, string $class = '', string $attr = ''): string {
        $lib = $GLOBALS['__LUCIDE'] ?? [];
        $body = $lib[$name] ?? ($lib['circle'] ?? '');
        $cls = trim('lc lc-' . preg_replace('/[^a-z0-9\-]/', '', $name) . ($class ? ' ' . $class : ''));
        $s = (int) $size;
        return '<svg class="' . htmlspecialchars($cls, ENT_QUOTES) . '" width="' . $s . '" height="' . $s . '"'
            . ' viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"'
            . ' stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"'
            . ($attr ? ' ' . $attr : '') . '>' . $body . '</svg>';
    }
    /** Echo helper. */
    function the_icon(string $name, int $size = 18, string $class = '', string $attr = ''): void {
        echo icon($name, $size, $class, $attr);
    }
